entries[353857] = { ["name"] = "Herbstwildling", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Wildlinge sind gutmütige, magische Wesen des Ardenwalds, die von starken und reinen Seelen angezogen werden.\"\nPakt:\nNachtfae\nVerkäufer:\nElwyn\nZone:\nArdenwald\nKosten:\n7500" }
entries[353858] = { ["name"] = "Winterwildling", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Wildlinge dienen im Kampf als Unterstützungseinheiten. Sie schützen ihre Verbündeten und machen feindliche Magie unschädlich.\"\nPakt:\nNachtfae\nVerkäufer:\nHerzogin Mynx\nZone:\nKorthia\nKosten:\n1000\nErfolg:\nIn der Offensive" }
entries[353859] = { ["name"] = "Sommerwildling", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser dickköpfige und rebellische Wildling ist nur sehr Wenigen gegenüber loyal. Doch mit diesen Wenigen geht er eine Bindung auf Lebenszeit ein.\"\nPakt:\nNachtfae\nBeute von:\nEntkommener Wildling\nZone:\nKorthia" }
entries[353860] = { ["name"] = "Frühjahrswildling", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei." }
entries[353861] = { ["name"] = "Verstärkt: Reflektierend", ["text"] = "Animabonus\n100 Meter Reichweite\nSofort\nElitegegner erhalten im Kampf regelmäßig einen reflektierenden Schild: Reflektiert 3 Sek. lang körperlichen Schaden auf Angreifer." }
entries[353866] = { ["name"] = "Obsidiangrabschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Am verdunkelten Himmel von Revendreth sieht man diese Kreaturen nicht kommen, bis es zu spät ist.\"\nPakt:\nVenthyr\nVerkäufer:\nChachi der Künstler\nZone:\nRevendreth\nKosten:\n7500" }
entries[353867] = { ["name"] = "Werfen", ["text"] = "100 Meter Reichweite\nSofort 6 sek. Abklingzeit\nWirft einen Faespeer auf einen schlundgebundenen Herold und zerrt ihn zu Euch herunter." }
entries[353868] = { ["name"] = "Aufgespießt", ["text"] = "Sofort\nVon Korayns Wurfspeer getroffen!" }
