entries[353872] = { ["name"] = "Grabschwinge von Sündensturz", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Da die Anima in Sündensturz wieder fließt, konnte die Steinhauerin diese Steingeborenen damit anreichern, was sie zu wertvollen Verbündeten in den kommenden Schlachten macht.\"\nPakt:\nVenthyr\nZone:\nRevendreth" }
entries[353873] = { ["name"] = "Bleiche Grabschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Grabschwingen kennen keine Furcht und sind nahezu unverwundbar, was für einen Angriff auf den Schlund perfekt ist.\"\nPakt:\nVenthyr\nVerkäufer:\nHerzogin Mynx\nZone:\nKorthia\nKosten:\n1000\nErfolg:\nIn der Offensive" }
entries[353875] = { ["name"] = "Elysischer Aquilon", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Da die Anima wieder in die Ewige Schmiede in der Bastion fließt, konnte die Produktion des Aquilonzenturios wieder aufgenommen werden.\"\nPakt:\nKyrianer\nZone:\nBastion" }
entries[353877] = { ["name"] = "Aquilon der Verschmähten", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese mächtigen Zenturionen wurden von den Verschmähten ursprünglich mithilfe gestohlener Baupläne erschaffen, doch heute machen sie sich in den gesamten Schattenlanden einen Namen.\"\nPakt:\nKyrianer\nBeute von:\nWilder Weltenknacker\nZone:\nKorthia" }
entries[353878] = { ["name"] = "Werfen", ["text"] = "40 Meter Reichweite\nWirken in 2 sek. 6 sek. Abklingzeit\nWirft einen Faespeer auf einen schlundgebundenen Herold und zerrt ihn zu Euch herunter." }
entries[353880] = { ["name"] = "Aquilon des Aszendenten", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der Aquilon kann blitzschnell Aspiranten, Provosten und sogar Aufgestiegene von Ort zu Ort transportieren. Hey, manchmal werden einem eben die Flügel müde.\"\nPakt:\nKyrianer\nVerkäufer:\nAdjutant Galos\nZone:\nBastion\nKosten:\n7500" }
