entries[353882] = { ["name"] = "Rasende Übertragung", ["text"] = "Runenschnitzmacht\nSofort\nDie durch 'Recht des Todes' erhaltene Stärke ist um 3% erhöht und hält 2 Sek. länger an. Während Ihr Euch im Effektbereich von 'Recht des Todes' aufhaltet, ist Eure Runenmachterzeugung um 20% erhöht.\nRunenschnitzen: Brust, Taille\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Todesritter" }
entries[353883] = { ["name"] = "Maldraxxische Leichenfliege", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Leichenfliegen waren einst in ganz Maldraxxus zu finden, aber viele starben aufgrund des Mangels an Anima. Da die Anima wieder fließt, schwärmen sie jetzt aus.\"\nPakt:\nNekrolords\nZone:\nMaldraxxus" }
entries[353884] = { ["name"] = "Majestätische Leichenfliege", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Nur die Truppen von Maldraxxus würden eine Leichenfliege als \"majestätisch\" bezeichnen.\"\nPakt:\nNekrolords\nVerkäufer:\nSu Zettai\nZone:\nMaldraxxus\nKosten:\n7500" }
entries[353885] = { ["name"] = "Schlachtfeldschwärmer", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Leichenfliegen werden von Leichengeruch stark angezogen und suchen ein aktives Schlachtfeld heim, sobald der erste Kämpfer fällt.\"\nPakt:\nNekrolords\nVerkäufer:\nHerzogin Mynx\nZone:\nKorthia\nKosten:\n1000\nErfolg:\nIn der Offensive" }
