entries[353929] = { ["name"] = "Bann der Banshee", ["text"] = "Unbegrenzte Reichweite\nSofort\nSylvanas belegt Ziele mit einem unersättlichen Leiden, das pro Sekunde 1 Schattenschaden verursacht. Dieser Effekt ist stapelbar. Bei Entfernung verschmilzt dieser Effekt zu einer Schattenlache auf dem Boden. Wenn ein Spielercharakter die Lache berührt, erhält er ' Bann der Banshee ' und verbraucht die Lache." }
entries[353930] = { ["name"] = "Bann der Banshee", ["text"] = "Unbegrenzte Reichweite\nSofort\nSylvanas belegt Ziele mit einem unersättlichen Leiden, das pro Sekunde 1 Schattenschaden verursacht. Dieser Effekt ist stapelbar. Bei Entfernung verschmilzt dieser Effekt zu einer Schattenlache auf dem Boden. Wenn ein Spielercharakter die Lache berührt, erhält er ' Bann der Banshee ' und verbraucht die Lache." }
entries[353931] = { ["name"] = "Schicksalszerrung", ["text"] = "300 Meter Reichweite\nSofort\nVerdreht die Fäden des Schicksals, die an mehreren Spielercharakteren hängen, und verursacht so 6 Sek. lang alle 2 Sek. 19968 Schattenschaden." }
entries[353935] = { ["name"] = "Schattendolch", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nSylvanas verschießt einen schreckenserfüllten Pfeil auf einen Spielercharakter, der 47924 Schattenschaden verursacht und allen anderen Spielercharakteren zusätzlich bis zu 111823 Schattenschaden zufügt. Der Schaden nimmt dabei mit zunehmender Entfernung zum Einschlagsort ab." }
entries[353936] = { ["name"] = "Donnernder Fokustee", ["text"] = "'Donnerfokustee' kann zusätzlich den Rückstoßeffekt von 'Knisternder Jadeblitz' sofort auslösen oder dafür sorgen, dass 'Rollen' und 'Chitorpedo' beim Einsatz eine Aufladung zurückerstatten und Euch um (240% der Angriffskraft) Gesundheit heilen." }
entries[353937] = { ["name"] = "Essenzborn", ["text"] = "100 Meter Reichweite\nSofort\n'Donnerfokustee' kann zusätzlich den Rückstoßeffekt von 'Knisternder Jadeblitz' sofort auslösen oder dafür sorgen, dass 'Rollen' und 'Chitorpedo' beim Einsatz eine Aufladung zurückerstatten und Euch um (240% der Angriffskraft) Gesundheit heilen." }
entries[353938] = { ["name"] = "Chistoß", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek. 30 sek. Abklingzeit\nSchleudert einen Schwall Chienergie bis zu 40 Meter vorwärts, wobei er allen Gegnern in seinem Weg (280% der Angriffskraft) Naturschaden zufügt und den Mönch sowie alle Verbündeten im Effektbereich um (220% der Angriffskraft) Gesundheit heilt. [ Braumeister : Beim Wirken von 'Chistoß' sind Vermeidungsmechaniken weiterhin aktiv ] [ Windläufer : 'Chistoß' erzeugt 1 Chi pro Gegner, dem Schaden zugefügt wurde, bis zu einem Maximum von 2 ]" }
