entries[354333] = { ["name"] = "Sündhafte Freuden", ["text"] = "Runenschnitzmacht\nSofort\nWenn Ihr [ Arkan : 'Freizaubern' ] [ Feuer : eine Aufladung von 'Feuerschlag' /\n\nFrost\n'Hirnfrost' ] verbraucht, wird die Abklingzeit von 'Spiegel der Qual' um 4 Sek. verringert. Wenn 'Spiegel der Qual' gebannt wird, wird die Abklingzeit um 45 Sek. verringert.\nRunenschnitzen: Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Magier" }
entries[354334] = { ["name"] = "Am Haken!", ["text"] = "300 Meter Reichweite\nSofort\nHakenschwanz hakt einen Spielercharakter für 3 Sek. an ihrem Schwanz fest und fügt ihm so 9 Sek. lang alle 3 Sek. 2182004 körperlichen Blutungsschaden zu." }
entries[354336] = { ["name"] = "Schlundrattenbrut", ["text"] = "Wirken in 1.5 sek.\nEntfesselt eine Schlundrattenbrut, die auf Befehl hin angreift." }
entries[354339] = { ["name"] = "Angriff!", ["text"] = "50 Meter Reichweite\nSofort 2 sek. Abklingzeit\nBefiehlt einer Ratte aus Eurer Brut, das gegnerische Ziel anzugreifen." }
