entries[354349] = { ["name"] = "Angesprungen", ["text"] = "60 Meter Reichweite\nSofort\nDie Schlundratte opfert sich, um den Gegner zu betäuben und ihm Schaden zuzufügen." }
entries[354351] = { ["name"] = "Sanktumdämmerstreitross", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Nur die mächtigsten Leutnants des Kerkermeisters erhalten diese Rösser, um durch die Hallen des Turms zu reiten.\"\nBeute von:\nDie Neun\nZone:\nSanktum der Herrschaft" }
entries[354352] = { ["name"] = "Seelengebundenes Dämmerstreitross", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ve'nari hat viele Methoden, im Schlund herumzuschleichen und die Pläne des Kerkermeisters zu durchkreuzen, darunter auch das Binden seiner Diener.\"\nBeute von:\nGeheimnisvolles Geschenk von Ve'nari\nZone:\nDer Schlund" }
entries[354353] = { ["name"] = "Gefallenes Streitross", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Schreie des Streitrosses hallen durch den Schlund, während es seinen endlosen Ritt durch das Land fortsetzt, immer auf der Suche nach einem Ausweg aus den endlosen Qualen, denen es ausgesetzt ist.\"\nBeute von:\nZone:\nDer Schlund" }
entries[354354] = { ["name"] = "Hand von Nilganihmaht", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Von allen Riesen, die es wagten, dem Kerkermeister zu trotzen, war Nilganihmaht der arroganteste. Für sein Vergehen wurde die abgetrennte Hand des Riesen in einem Schleier der Qualen verborgen und die Ringe, die sie zurückbringen könnten, wurden über den ganzen Schlund verstreut.\"\nZone:\nDer Schlund" }
entries[354355] = { ["name"] = "Hand von Salaranga", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Salaranga war die gerissenste ihrer Art und versteckte sich im Bestienlabyrinth. Sie griff den Verbannten mit einer Horde aus verbündeten Bestien an, auch wenn dies letztendlich keinen Unterschied machte.\"\nErfolg:\nDie Ketten durchbrechen\nZone:\nKorthia und der Schlund" }
entries[354356] = { ["name"] = "Bernsteinsplitterfell", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die leuchtenden Farben der korthianischen Wildtiere deuten darauf hin, dass ihnen entweder nur wenige Raubtiere auflauern oder sie sich zu wehren wissen.\"\nVerkäufer:\nHerzogin Mynx\nZone:\nKorthia\nVorstoß des Todes - Respektvoll\nKosten:\n5.000" }
entries[354357] = { ["name"] = "Blutrotes Splitterfell", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Als Korthia in den Schlund gezogen wurde, überlebten nur wenige besonders widerstandsfähige Arten.\"\nBeute von:\nMalbog\nZone:\nKorthia" }
entries[354358] = { ["name"] = "Finsterpranke", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Finsterpranke ist ein älteres Splitterfell und trat den Korthianern zumeist recht zahm und freundlich gegenüber. Man glaubte, er sei in der Katastrophe verloren gegangen.\"\nZone:\nKorthia" }
entries[354359] = { ["name"] = "Grimmige Klingenschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Klingenschwingen halten sich im Allgemeinen von anderen korthianischen Spezies fern, aber mit etwas Zeit und Geduld lassen auch sie sich zähmen.\"\nBeute von:\nVorräte des Vorstoßes des Todes\nZone:\nKorthia" }
entries[354360] = { ["name"] = "Granatklingenschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Korthia war einst für seine leuchtend roten Blumen bekannt. Von mehreren Wildtieren weiß man, dass sie diese verzehrten oder sich darin wälzten, um eine leuchtend rote Färbung anzunehmen.\"\nBeute von:\nReliwik der Trotzige\nZone:\nKorthia" }
entries[354361] = { ["name"] = "Dämmerlichtklingenschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Klingenschwingen sind in ganz Korthia beheimatet. Sie bauen ihre Nester auf hohen Hügeln und in Bäumen.\"\nZone:\nKorthia" }
entries[354362] = { ["name"] = "Wandernde Ardenhirschkuh", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese neugierige und wissbegierige Hirschkuh will ihren Besitzer nicht beunruhigen, aber sie lässt sich eben leicht ablenken. Besonders bei all den neuen Dingen, die es in Korthia zu sehen gibt.\"\nZone:\nKorthia" }
entries[354363] = { ["name"] = "Finsteres Omen", ["text"] = "Sofort\nSchicksalsschreiber Roh-Kalo bindet mehrere Spielercharaktere an Runen auf dem Webstuhl der Schicksale.\n\nFalls ein gebundener Spielercharakter nach 9 Sek. seine zugewiesene Rune berührt, fügt der Schicksalsschreiber allen Spielercharakteren in der Rune 19968 Schattenschaden zu.\n\nWenn eine Rune abläuft, ohne dass sich der daran gebundene Spielercharakter in ihr befindet, fügt der Schicksalsschreiber allen Spielercharakteren 107829 Schattenschaden zu." }
