entries[354366] = { ["name"] = "Schleier der Dunkelheit", ["text"] = "Unbegrenzte Reichweite\nSofort\nSylvanas Windläufer ist mit Abstand eine der talentiertesten Kämpferinnen Azeroths. Sie ist in der Lage, mehrere Fähigkeiten in schneller Folge auszuführen und je nach Kampfsituation schnell ihre Position zu wechseln. Wenn sie unter dem Einfluss von ' Windläufer ' steht, treffen Zauber und Fähigkeiten Sylvanas dort, wo sie ' Windläufer ' gewirkt hat." }
