entries[354374] = { ["name"] = "Bann der Banshee", ["text"] = "Unbegrenzte Reichweite\nSofort\nSylvanas belegt Ziele mit einem unersättlichen Leiden, das pro Sekunde 1 Schattenschaden verursacht. Dieser Effekt ist stapelbar. Bei Entfernung verschmilzt dieser Effekt zu einer Schattenlache auf dem Boden. Wenn ein Spielercharakter die Lache berührt, erhält er ' Bann der Banshee ' und verbraucht die Lache." }
entries[354376] = { ["name"] = "Wütende Tritte", ["text"] = "Sofort 20 sek. Abklingzeit\nVerschwindet vor Gegnern, indem Ihr an Eurer aktuellen Position eine Staubwolke erschafft, die verbündete Einheiten für 5 Sek. verbirgt.\n\nTubbins kann innerhalb der Staubwolke Tee servieren." }
