entries[354383] = { ["name"] = "Vantusrune: Sanktum der Herrschaft", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\nStellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Sanktum der Herrschaft ein, was Eure Vielseitigkeit um 1875 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen." }
